SELECT 
FROM exchange_batch b
LEFT JOIN dealer_company dc ON dc.company_id = b.owner_company_id


    b.request_id = #{requestId}

        AND b.owner_company_id = #{scopeCompanyId}

SELECT d.service_code_id, COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(d.service_code_snapshot, '$.code')), ''), sc.code) AS service_code, a.id AS service_account_id, COALESCE(a.cors_account_id, d.cors_account_id) AS cors_account_id, COALESCE(a.account, d.account) AS account_name, d.status FROM exchange_detail d JOIN exchange_batch b ON b.id = d.exchange_batch_id LEFT JOIN service_code sc ON sc.id = d.service_code_id LEFT JOIN service_account a ON a.exchange_detail_id = d.id WHERE b.request_id = #{requestId}
AND b.owner_company_id = #{scopeCompanyId}
ORDER BY d.detail_index ASC, d.id ASC
